        const auto p5 = T*c7;
        const auto p6 = c6*exp(p5);
        const auto p7 = c1 + p6;
        const auto p8 = exp(T*c5);
        const auto p9 = c4*p8;
        const auto p10 = c0 + p9;
        const auto p11 = (p10*p10*p10);
        const auto p12 = p11*rho;
        const auto p13 = FWr*p12;
        const auto p14 = (1.0/(T));
        const auto p15 = p14*p7;
        const auto p16 = 4.0*FWb;
        const auto p17 = -0.6023*p13 + p15*p16;
        const auto p18 = p7/p17;
        const auto p19 = sqrt(70.0);
        const auto p20 = (1.0/(p7));
        const auto p21 = pow(p20, -0.661046);
        const auto p22 = (p1*p1);
        const auto p23 = log(T*p20);
        const auto p24 = p12*p23;
        const auto p25 = 1.2041344220999999 - 1.0536431417999998*p23;
