        dF = -p2*p30*p35/p29;
        dFrho = p2*(-FWr*p37*p39 + 0.6023*FWrb*p37*p48 - 0.6023*FWrr*p12*p51 - p19*p21*p22*p26*p38*p40*p44*p45*rho*(-27.73062524085627*p13*p41 + p42*(1.26784727581608*p11*rho - 0.76219454232972*p24 - p25) + 92.08243480277693));
